# --- 리스너를 만든다 ---

@Component
public class AuthEventListener {
    @EventListener
    public void onSuccess(AuthenticationSuccessEvent e) {
        System.out.println(">>> SUCCESS " + e.getAuthentication().getName()
                + " (" + e.getAuthentication().getClass().getSimpleName() + ")");
    }

    @EventListener
    public void onInteractive(InteractiveAuthenticationSuccessEvent e) {
        System.out.println(">>> INTERACTIVE " + e.getAuthentication().getName()
                + " by " + e.getGeneratedBy().getSimpleName());
    }

    @EventListener
    public void onFailure(AbstractAuthenticationFailureEvent e) {
        System.out.println(">>> FAILURE " + e.getAuthentication().getName()
                + " " + e.getClass().getSimpleName()
                + " " + e.getException().getClass().getSimpleName());
    }
}

